import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const WorkingAdminLogin = () => {
  const [username, setUsername] = useState('admin');
  const [password, setPassword] = useState('123');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      console.log('Making direct API call...');

      const response = await axios.post('http://localhost:8080/api/auth/login', {
        usernameOrEmail: username,
        password: password
      });

      console.log('Login response:', response.data);

      if (response.data.token) {
        // Store in localStorage
        localStorage.setItem('token', response.data.token);
        localStorage.setItem('user', JSON.stringify(response.data));

        // Force redirect to analytics
        window.location.href = '/analytics';
      } else {
        setError('No token received');
      }
    } catch (error) {
      console.error('Login error:', error);
      setError(error.response?.data?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    }}>
      <div style={{
        width: '450px',
        padding: '40px',
        background: 'white',
        borderRadius: '12px',
        boxShadow: '0 15px 35px rgba(0,0,0,0.1)'
      }}>
        <h2 style={{ textAlign: 'center', marginBottom: '10px', color: '#333' }}>
          🔧 Admin Login (Working Version)
        </h2>

        <p style={{ textAlign: 'center', marginBottom: '30px', color: '#666', fontSize: '14px' }}>
          Direct API call - no context issues
        </p>

        {error && (
          <div style={{
            padding: '12px',
            marginBottom: '20px',
            backgroundColor: '#f8d7da',
            color: '#721c24',
            border: '1px solid #f5c6cb',
            borderRadius: '6px',
            fontSize: '14px'
          }}>
            ❌ {error}
          </div>
        )}

        <div style={{
          backgroundColor: '#e7f3ff',
          padding: '15px',
          borderRadius: '8px',
          marginBottom: '25px',
          border: '1px solid #b3d9ff'
        }}>
          <p style={{ margin: '0', fontSize: '14px', color: '#0066cc' }}>
            <strong>🔑 Working Credentials:</strong><br/>
            Username: <code style={{ background: '#f0f0f0', padding: '2px 6px', borderRadius: '3px' }}>admin</code><br/>
            Password: <code style={{ background: '#f0f0f0', padding: '2px 6px', borderRadius: '3px' }}>123</code>
          </p>
        </div>

        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: 'bold', color: '#333' }}>
              👤 Username
            </label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                border: '2px solid #ddd',
                borderRadius: '6px',
                fontSize: '16px',
                transition: 'border-color 0.3s'
              }}
              placeholder="Enter username"
              required
            />
          </div>

          <div style={{ marginBottom: '25px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: 'bold', color: '#333' }}>
              🔒 Password
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                border: '2px solid #ddd',
                borderRadius: '6px',
                fontSize: '16px',
                transition: 'border-color 0.3s'
              }}
              placeholder="Enter password"
              required
            />
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              padding: '14px',
              backgroundColor: loading ? '#ccc' : '#007bff',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background-color 0.3s'
            }}
            disabled={loading}
          >
            {loading ? '🔄 Logging in...' : '🚀 Login to Admin Panel'}
          </button>
        </form>

        <div style={{ textAlign: 'center', marginTop: '25px', paddingTop: '20px', borderTop: '1px solid #eee' }}>
          <p style={{ margin: '0 0 10px 0', fontSize: '12px', color: '#666' }}>
            💡 This version uses direct API calls
          </p>
          <a href="/simple-login" style={{ color: '#007bff', textDecoration: 'none', fontSize: '14px' }}>
            ← Back to Regular Login
          </a>
        </div>
      </div>
    </div>
  );
};

export default WorkingAdminLogin;
